<?php
require_once __DIR__ . '/layout.php';
require_once __DIR__ . '/lib/vendeurs.php';
$user = app_current_user();
$access = $user ? seller_access((int) $user['id']) : null;
$plans = seller_plans();
$selected = $_GET['formule'] ?? ($access['plan_code'] ?? 'essentiel');
if (!is_string($selected) || !isset($plans[$selected])) { $selected = 'essentiel'; }
$canRequest = $user && (!$access || in_array($access['status'], ['rejected', 'cancelled'], true));
app_page_start('Devenir vendeur', 'vendeur');
?>
<section class="seller-hero"><div class="container seller-hero-inner"><div><p class="eyebrow">Un nouvel espace pour vos ventes</p><h1>Donnez une nouvelle valeur<br>aux biens que vous vendez.</h1><p>Vous avez déjà un compte acheteur ? Choisissez votre formule et demandez votre accès vendeur. Vous pourrez continuer à enchérir sur les annonces des autres vendeurs.</p><div class="row"><a class="button button-blue" href="<?= app_is_seller($user) ? 'creer_enchere.php' : ($canRequest ? '#demande' : '#formules') ?>"><?= app_is_seller($user) ? 'Publier une annonce' : 'Découvrir les formules' ?> <?= app_icon('arrow') ?></a><a class="button button-outline" href="<?= $user ? 'compte.php' : 'login.php' ?>"><?= $user ? 'Mon espace acheteur' : 'J’ai déjà un compte' ?></a></div></div><div class="seller-hero-art" aria-hidden="true"><div><?= app_icon('tag') ?>Vos annonces</div><div><?= app_icon('hammer') ?>Les offres reçues</div><div><?= app_icon('user') ?>Un compte acheteur et vendeur</div></div></div></section>
<div class="container section">
<?php if (in_array($_GET['resultat'] ?? null, ['envoyee', 'retiree'], true)) { app_notice($_GET['resultat'] === 'envoyee' ? 'Votre demande est enregistrée. Elle sera examinée par un administrateur.' : 'Votre demande a été retirée.', 'success'); } ?>
<?php if ($access): ?><section class="status-card"><p class="eyebrow">Votre espace vendeur</p><h2><?= app_escape(seller_status_name($access['status'])) ?></h2><dl><div><dt>Formule</dt><dd><?= app_escape(seller_plan_name($access['plan_code'])) ?></dd></div><div><dt>Demande enregistrée</dt><dd><?= app_escape(date('d/m/Y à H:i', strtotime($access['requested_at']))) ?></dd></div><div><dt>Vos droits acheteur</dt><dd>Toujours disponibles</dd></div></dl>
<?php if ($access['status'] === 'active'): ?><p>Vous pouvez publier des annonces et suivre leurs offres depuis votre espace vendeur.</p><div class="row"><a class="button button-blue" href="creer_enchere.php">Créer une annonce <?= app_icon('plus') ?></a><a class="button button-outline" href="mes_annonces.php">Mes annonces</a></div>
<?php elseif ($access['status'] === 'pending'): ?><p>Votre choix de formule a été transmis. La publication sera disponible après validation de l’accès vendeur.</p><form method="post" action="traitement_demande_vendeur.php"><input type="hidden" name="csrf_token" value="<?= app_escape(app_csrf_token()) ?>"><input type="hidden" name="version" value="<?= (int) $access['version'] ?>"><button class="button button-outline button-small" name="action" value="withdraw">Retirer ma demande</button></form>
<?php elseif ($access['status'] === 'suspended'): ?><p>Votre accès à la publication est suspendu. Vos anciennes annonces et vos offres restent consultables dans votre compte.</p><?php endif; ?>
<?php if ($access['reason'] !== ''): ?><div class="notice"><strong>Message de l’administration</strong><p style="margin:8px 0 0;white-space:pre-wrap"><?= app_escape($access['reason']) ?></p></div><?php endif; ?>
</section><?php endif; ?>
<div class="benefits-grid"><article class="benefit"><h2><?= app_icon('tag') ?>Publiez vos biens</h2><p>Présentez chaque lot avec une photo, une description, un prix de départ et une date de fin.</p></article><article class="benefit"><h2><?= app_icon('hammer') ?>Suivez les enchères</h2><p>Retrouvez les offres reçues et l’évolution du prix sur les fiches de vos annonces.</p></article><article class="benefit"><h2><?= app_icon('shield') ?>Gardez vos repères</h2><p>Votre compte reste acheteur. Les lots que vous avez publiés restent associés à votre compte.</p></article></div>
<section id="formules"><div class="plans-heading"><p class="eyebrow">Les formules vendeur</p><h2>Un accès adapté à votre projet.</h2><p class="muted">Les conditions de votre formule sont confirmées lors de l’examen de votre demande. Aucun paiement n’est effectué sur cette page.</p></div><div class="plans-grid"><?php foreach ($plans as $code => $plan): ?><article class="plan-card <?= $code === 'standard' ? 'recommended' : '' ?>"><h3><?= app_escape($plan['name']) ?></h3><p><?= app_escape($plan['intro']) ?></p><ul><?php foreach ($plan['features'] as $feature): ?><li><?= app_icon('check') ?><span><?= app_escape($feature) ?></span></li><?php endforeach; ?></ul><p class="plan-price">Conditions sur devis<small>Après étude de votre demande</small></p><?php if ($canRequest): ?><a class="button button-blue button-wide" href="devenir_vendeur.php?formule=<?= $code ?>#demande">Choisir <?= app_escape($plan['name']) ?></a><?php elseif (!$user): ?><a class="button button-blue button-wide" href="login.php?inscription=1">Créer mon compte acheteur</a><?php else: ?><a class="button button-light button-wide" href="compte.php">Consulter mon compte</a><?php endif; ?></article><?php endforeach; ?></div></section>
<?php if ($canRequest): ?><section class="seller-request panel narrow" id="demande"><p class="eyebrow">À vous de choisir</p><h2>Présentez votre projet de vente.</h2><p class="muted">Votre demande est liée à votre compte. Seule l’administration peut activer votre accès vendeur.</p><form action="traitement_demande_vendeur.php" method="post"><input type="hidden" name="csrf_token" value="<?= app_escape(app_csrf_token()) ?>"><input type="hidden" name="action" value="request"><input type="hidden" name="version" value="<?= (int) ($access['version'] ?? 0) ?>"><fieldset><legend>Votre formule</legend><div class="radio-plans"><?php foreach ($plans as $code => $plan): ?><label><input type="radio" name="plan" value="<?= $code ?>" <?= $selected === $code ? 'checked' : '' ?> required><?= app_escape($plan['name']) ?></label><?php endforeach; ?></div></fieldset><div class="form-columns"><div class="field"><label for="organisation">Organisation (facultatif)</label><input id="organisation" name="organisation" maxlength="150" autocomplete="organization" value="<?= app_escape($access['organisation'] ?? '') ?>"></div><div class="field"><label for="telephone">Téléphone (facultatif)</label><input type="tel" id="telephone" name="telephone" maxlength="40" autocomplete="tel" value="<?= app_escape($access['telephone'] ?? '') ?>"></div></div><div class="field"><label for="projet">Quels biens souhaitez-vous vendre ?</label><textarea name="projet" id="projet" maxlength="2000" required placeholder="Décrivez les biens et votre projet de vente…"><?= app_escape($access['project'] ?? '') ?></textarea><small>Ces informations sont transmises à l’administration, elles ne sont pas affichées sur le catalogue.</small></div><div class="form-actions"><button type="submit" class="button button-blue">Envoyer ma demande <?= app_icon('arrow') ?></button><small>L’activation suit la validation de votre demande.</small></div></form></section><?php endif; ?>
</div><?php app_page_end(); ?>
